import pandas as pd


def run(inputs: dict) -> dict:
    trades = inputs["trades"].copy()

    # Ensure deterministic ordering: by account/symbol group, then chronological,
    # then trade_id as tie-breaker (matches cursor ORDER BY trade_ts, trade_id).
    trades = trades.sort_values(
        ["account_id", "symbol", "trade_ts", "trade_id"], kind="mergesort"
    ).reset_index(drop=True)

    # state[(account_id, symbol)] -> list of [lot_trade_id, remaining_qty, price]
    state = {}
    sell_rows = []

    for row in trades.itertuples(index=False):
        key = (row.account_id, row.symbol)
        lots = state.setdefault(key, [])

        if row.side == "BUY":
            lots.append([row.trade_id, row.qty, row.price])
        elif row.side == "SELL":
            still_to_sell = row.qty
            realized_pnl = 0.0
            matched_qty = 0

            for lot in lots:
                if still_to_sell <= 0:
                    break
                if lot[1] <= 0:
                    continue
                take = min(lot[1], still_to_sell)
                realized_pnl += take * (row.price - lot[2])
                lot[1] -= take
                still_to_sell -= take
                matched_qty += take

            short_qty = row.qty - matched_qty
            sell_rows.append(
                {
                    "trade_id": row.trade_id,
                    "matched_qty": matched_qty,
                    "short_qty": short_qty,
                    "realized_pnl": realized_pnl,
                }
            )
        # any other side value is ignored (not specified by legacy spec)

    lot_rows = []
    for (acct, sym), lots in state.items():
        for lot_trade_id, remaining, price in lots:
            if remaining > 0:
                lot_rows.append(
                    {
                        "lot_trade_id": lot_trade_id,
                        "account_id": acct,
                        "symbol": sym,
                        "remaining_qty": remaining,
                        "price": price,
                    }
                )

    sell_results = pd.DataFrame(
        sell_rows, columns=["trade_id", "matched_qty", "short_qty", "realized_pnl"]
    )
    open_lots = pd.DataFrame(
        lot_rows,
        columns=["lot_trade_id", "account_id", "symbol", "remaining_qty", "price"],
    )

    if len(sell_results) > 0:
        sell_results = sell_results.astype(
            {
                "trade_id": "int64",
                "matched_qty": "int64",
                "short_qty": "int64",
                "realized_pnl": "float64",
            }
        )
    else:
        sell_results = pd.DataFrame(
            {
                "trade_id": pd.Series(dtype="int64"),
                "matched_qty": pd.Series(dtype="int64"),
                "short_qty": pd.Series(dtype="int64"),
                "realized_pnl": pd.Series(dtype="float64"),
            }
        )

    if len(open_lots) > 0:
        open_lots = open_lots.astype(
            {
                "lot_trade_id": "int64",
                "account_id": "int64",
                "symbol": "object",
                "remaining_qty": "int64",
                "price": "float64",
            }
        )
    else:
        open_lots = pd.DataFrame(
            {
                "lot_trade_id": pd.Series(dtype="int64"),
                "account_id": pd.Series(dtype="int64"),
                "symbol": pd.Series(dtype="object"),
                "remaining_qty": pd.Series(dtype="int64"),
                "price": pd.Series(dtype="float64"),
            }
        )

    return {"sell_results": sell_results, "open_lots": open_lots}
